ALTER TABLE public.tenant_settings ADD COLUMN sales_numbering jsonb NOT NULL DEFAULT '{"order":"PO/{CLIENT}/{YYYY}/{MM}/{SEQ}","invoice":"INV/{CLIENT}/{YYYY}/{MM}/{SEQ}","quotation":"QUO/{CLIENT}/{YYYY}/{MM}/{SEQ}"}'::jsonb;
UPDATE public.tenant_settings SET sales_numbering=CASE WHEN doc_numbering->>'invoice'='{SEQ}/SDY/INV/{CLIENT}/{MM}{YYYY}' THEN sales_numbering|| (doc_numbering-'invoice') ELSE sales_numbering||doc_numbering END;
CREATE OR REPLACE FUNCTION public.next_sales_number(p_client text,p_type text,p_date date) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid:=public.active_tenant_id(); code text; n bigint; fmt text; BEGIN IF NOT public.can_access_tenant_module(tid,CASE WHEN p_type='quotation' THEN 'quotations' ELSE 'orders' END) THEN RAISE EXCEPTION 'Modul tidak berizin'; END IF; code:=regexp_replace(upper(btrim(p_client)),'[^A-Z0-9]','','g'); IF code='' OR p_date IS NULL THEN RAISE EXCEPTION 'Client dan tanggal wajib'; END IF; SELECT sales_numbering->>p_type INTO fmt FROM public.tenant_settings WHERE tenant_id=tid; IF fmt IS NULL OR position('{SEQ}' in fmt)=0 THEN RAISE EXCEPTION 'Format nomor harus memuat {SEQ}'; END IF; INSERT INTO public.document_sequences(tenant_id,client_code,document_type,sequence) VALUES(tid,code,p_type,1) ON CONFLICT(tenant_id,client_code,document_type) DO UPDATE SET sequence=public.document_sequences.sequence+1 RETURNING sequence INTO n; RETURN replace(replace(replace(replace(replace(fmt,'{CLIENT}',code),'{KODE_CLIENT}',code),'{YYYY}',to_char(p_date,'YYYY')),'{MM}',to_char(p_date,'MM')),'{SEQ}',n::text); END $$;
CREATE FUNCTION public.track_sales_sequence() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE num text; typ text; n bigint; code text; BEGIN IF TG_TABLE_NAME='quotations' THEN num:=NEW.quotation_number;typ:='quotation'; ELSE num:=NEW.invoice_number;typ:='invoice'; END IF; code:=regexp_replace(upper(NEW.client_name),'[^A-Z0-9]','','g'); IF num ~ '^(INV|PO|QUO)/[^/]+/[0-9]{4}/[0-9]{2}/[0-9]+$' THEN n:=(regexp_match(num,'/([0-9]+)$'))[1]::bigint; INSERT INTO public.document_sequences(tenant_id,client_code,document_type,sequence) VALUES(NEW.tenant_id,code,typ,n) ON CONFLICT(tenant_id,client_code,document_type) DO UPDATE SET sequence=GREATEST(public.document_sequences.sequence,EXCLUDED.sequence); END IF; IF TG_TABLE_NAME='orders' AND NEW.order_number ~ '^PO/[^/]+/[0-9]{4}/[0-9]{2}/[0-9]+$' THEN n:=(regexp_match(NEW.order_number,'/([0-9]+)$'))[1]::bigint; INSERT INTO public.document_sequences(tenant_id,client_code,document_type,sequence) VALUES(NEW.tenant_id,code,'order',n) ON CONFLICT(tenant_id,client_code,document_type) DO UPDATE SET sequence=GREATEST(public.document_sequences.sequence,EXCLUDED.sequence); END IF; RETURN NEW; END $$;
CREATE TRIGGER sales_sequence_sync AFTER INSERT OR UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.track_sales_sequence();
CREATE TRIGGER sales_sequence_sync AFTER INSERT OR UPDATE ON public.quotations FOR EACH ROW EXECUTE FUNCTION public.track_sales_sequence();
CREATE FUNCTION public.invoice_payment_scope_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.order_id IS DISTINCT FROM OLD.order_id OR NEW.amount IS DISTINCT FROM OLD.amount OR NEW.payment_date IS DISTINCT FROM OLD.payment_date OR NEW.method IS DISTINCT FROM OLD.method OR NEW.reference IS DISTINCT FROM OLD.reference OR NEW.notes IS DISTINCT FROM OLD.notes OR NEW.created_by IS DISTINCT FROM OLD.created_by OR OLD.voided_at IS NOT NULL THEN RAISE EXCEPTION 'Paiement immutable; gunakan void dengan alasan'; END IF; RETURN NEW; END $$;
CREATE TRIGGER payment_immutable BEFORE UPDATE ON public.payments FOR EACH ROW EXECUTE FUNCTION public.invoice_payment_scope_guard();
COMMENT ON COLUMN public.tenant_settings.doc_numbering IS 'DEPRECATED: sales document numbering uses sales_numbering; legacy numbers preserved';